package com.arqly.backend.entity; import jakarta.persistence.*;
@Entity @Table(name="financial_categories") public class FinancialCategory extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="tenant_id",nullable=false)private Tenant tenant;@Column(nullable=false)private String name;@Enumerated(EnumType.STRING)@Column(nullable=false)private FinancialCategoryType type;@Column(nullable=false)private boolean active=true;public Tenant getTenant(){return tenant;}public void setTenant(Tenant v){tenant=v;}public String getName(){return name;}public void setName(String v){name=v;}public FinancialCategoryType getType(){return type;}public void setType(FinancialCategoryType v){type=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}}
